insert into flashcards (id, profile_id, course, card_number, total_cards, topic, category, question, key_aspect, comparison, explanation, retention_stability) values
('11111111-aaaa-bbbb-cccc-111111111111', '11111111-1111-1111-1111-111111111111', 'CS301 OPERATING SYSTEMS', 14, 32, 'Virtual Memory & Paging', 'Memory Management', 'What is the primary trade-off between Inverted Page Tables and Multi-Level Hierarchical Paging?', 'Physical memory overhead vs. translation lookup speed and TLB miss penalties.', '{"leftTitle": "INVERTED TABLE", "leftValue": "Fixed RAM Footprint", "leftSub": "Bound by physical RAM frames", "rightTitle": "HIERARCHICAL", "rightValue": "Multi-Access Latency", "rightSub": "Memory page walks (CR3 depth)"}', 'Inverted page tables allocate one entry per frame in physical memory rather than per virtual page, drastically lowering RAM consumption for large 64-bit addresses. However, linear search or hash bucket collisions necessitate extra memory lookups upon TLB misses compared to indexed hierarchical page directories.', 68),
('22222222-aaaa-bbbb-cccc-222222222222', '11111111-1111-1111-1111-111111111111', 'CS301 OPERATING SYSTEMS', 15, 32, 'TLB Shootdown Protocol', 'Concurrency & SMP', 'Why is an inter-processor interrupt (IPI) required during a multi-core TLB Shootdown?', 'Cache coherency across distributed hardware TLBs on shared address spaces.', '{"leftTitle": "SINGLE CORE", "leftValue": "Local INVLPG", "leftSub": "Single instruction cycle flush", "rightTitle": "SMP MULTI-CORE", "rightValue": "IPI Synchronization", "rightSub": "Stalls cores until acknowledge"}', 'When modifying page table entries (PTE) that may be cached across other CPU cores, the modifying CPU must broadcast an IPI to invalidate stale translations in each core''s local TLB before freeing or remapping memory.', 82),
('33333333-aaaa-bbbb-cccc-333333333333', '11111111-1111-1111-1111-111111111111', 'CS312 ALGORITHM DESIGN', 16, 32, '0/1 Knapsack vs Unbounded Knapsack', 'Dynamic Programming', 'How does the state transition recurrence distinguish between 0/1 and Unbounded Knapsack?', 'Reference index in the DP table: prior row (i - 1) versus current row (i).', '{"leftTitle": "0/1 KNAPSACK", "leftValue": "dp[i-1][w - w[i]]", "leftSub": "Prevents multiple item inclusions", "rightTitle": "UNBOUNDED", "rightValue": "dp[i][w - w[i]]", "rightSub": "Allows infinite re-sampling of item i"}', '0/1 Knapsack samples the subproblem without the current item (row i-1), ensuring each item is used at most once. Unbounded Knapsack re-samples the current row (row i) with reduced capacity, permitting infinite inclusion.', 42);
insert into drill_questions (id, profile_id, course, title, context, problem, capacity, weights, values, options, selected_option_id, verified_label, matrix, explanation) values
('44444444-aaaa-bbbb-cccc-444444444444', '11111111-1111-1111-1111-111111111111', 'CS312 Algorithm Design', '0/1 Knapsack State Space Optimization', 'Dynamic Programming • Memoization | 58% Past Fail Rate', 'Given a discrete set of items with weights W = [2, 3, 4, 5] and values V = [3, 4, 5, 6], with maximum sack capacity C = 5. What is the optimal subproblem recurrence relation for computing dp[i][w]?', 'C = 5', '[2, 3, 4, 5]', '[3, 4, 5, 6]', '[{"id": "opt-a", "formula": "dp[i][w] = max(dp[i-1][w], dp[i-1][w - w[i]] + v[i])", "description": "Include or exclude item i using previous item states (i-1)", "isCorrect": true}, {"id": "opt-b", "formula": "dp[i][w] = dp[i-1][w] + dp[i][w - w[i]]", "description": "Additive branch without bounds optimization", "isCorrect": false}, {"id": "opt-c", "formula": "dp[i][w] = max(dp[i][w-1], dp[i-1][w])", "description": "LCS recurrence omitting item weights and values", "isCorrect": false}, {"id": "opt-d", "formula": "dp[i][w] = min(dp[i-1][w], v[i] * w)", "description": "Minimization heuristic for greedy bounds", "isCorrect": false}]', 'opt-a', 'Optimal Recurrence Verified', '{"capacities": [0, 1, 2, 3, 4, 5], "rows": [{"label": "i=0", "cells": [{"val": 0}, {"val": 0}, {"val": 3}, {"val": 3}, {"val": 3}, {"val": 3}]}, {"label": "i=1", "cells": [{"val": 0}, {"val": 0}, {"val": 3}, {"val": 4}, {"val": 4}, {"val": 7, "highlight": true}]}, {"label": "i=2", "cells": [{"val": 0}, {"val": 0}, {"val": 3}, {"val": 4}, {"val": 5}, {"val": 7, "highlight": true}]}]}', '0/1 Knapsack strictly samples from prior row index i - 1 when factoring chosen item value. Using current row i enables reuse, turning it into Unbounded Knapsack.'),
('55555555-aaaa-bbbb-cccc-555555555555', '11111111-1111-1111-1111-111111111111', 'CS312 Algorithm Design', 'Longest Common Subsequence (LCS) State Transitions', 'String Recurrence • 2D Dynamic Programming', 'Given two sequences X[1..m] and Y[1..n], what is the recurrence relation when X[i] == Y[j] vs when X[i] != Y[j]?', 'O(m × n)', 'Characters X[i], Y[j]', 'Length count', '[{"id": "opt-lcs-a", "formula": "if X[i]==Y[j]: dp[i-1][j-1]+1; else max(dp[i-1][j], dp[i][j-1])", "description": "Extend diagonal match by 1; take max of adjacent predecessors otherwise", "isCorrect": true}, {"id": "opt-lcs-b", "formula": "dp[i][j] = dp[i-1][j-1] + (X[i] == Y[j] ? 1 : 0)", "description": "Single diagonal transition without branch pruning", "isCorrect": false}]', 'opt-lcs-a', 'Diagonal Subproblem Proved', '{"capacities": [0, 1, 2, 3, 4], "rows": [{"label": "j=0", "cells": [{"val": 0}, {"val": 0}, {"val": 0}, {"val": 0}, {"val": 0}]}, {"label": "j=1", "cells": [{"val": 0}, {"val": 1, "highlight": true}, {"val": 1}, {"val": 1}, {"val": 1}]}]}', 'When characters match, the optimal prefix is extended unconditionally by 1 from dp[i-1][j-1]. When disjoint, the subproblem inherits the best of either eliminating X[i] or Y[j].');
